"use strict";(globalThis.webpackChunkgrc||=[]).push([[68611],{396(e){e.exports=JSON.parse('{"citeKey":"wu2003generalself","slug":"wu-2003-general-self-6c80","title":"A General Self-adaptive Task Scheduling System for Non-dedicated Heterogeneous Computing","authors":["M. Wu","X.-H. Sun"],"venue":"The IEEE International Conference on Cluster Computing, 2003, Hong Kong","type":"Conference","entryType":"inproceedings","date":"December, 2003","year":2003,"era":"iit","month":12,"doi":"10.1109/clustr.2003.1253334","abstract":"The efforts to construct a national scale grid computing environment has brought unprecedented computing capacity. Exploiting this complex infrastructure requires efficient middleware to support the execution of a distributed application, composed of a set of subtasks, for best performance. This presents the challenge how to schedule these subtasks in shared heterogeneous systems. Current work has several limitations. Most scheduling systems are based on determined estimation of task completion time. Current application-level scheduling algorithms are too closely coupled with application internal structures. The application performance may suffer when some resources represent abnormal usage pattern during applications execution. To address these issues, we develop a prototype of Grid Harvest Service (GHS) to provide dynamic and self-adaptive task scheduling. Experimental results show GHS outperforms current systems in scheduling large applications in a non dedicated heterogeneous environment.","hasAbstract":true,"lede":"To address these issues, we develop a prototype of Grid Harvest Service (GHS) to provide dynamic and self-adaptive task scheduling.","links":{"pdf":"https://grc.iit.edu/papers/2003/wu-2003-general-self-6c80.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":["ghs"],"memberAuthors":["sun-xian-he"]}')}}]);